def summarize_sales(records):
    sales_summary = {}

    for name, category, quantity, price in records:
        if category not in sales_summary:
            sales_summary[category] = {
                "items": 0,
                "revenue": 0,
                "top_product": None
            }

        sales_summary[category]["items"] += quantity
        sales_summary[category]["revenue"] += quantity * price

        # Update top product if necessary
        if sales_summary[category]["top_product"] is None or (
            (sales_summary[category]["revenue"] > sales_summary[sales_summary[category]["top_product"]]["revenue"]) or 
            (sales_summary[category]["revenue"] == sales_summary[sales_summary[category]["top_product"]]["revenue"] and name < sales_summary[sales_summary[category]["top_product"]]["name"])
        ):
            sales_summary[category]["top_product"] = name

    return sales_summary

def sensor_summary(entries):
    if not entries:
        return {}

    sensor_data = {}
    for sensor_id, reading, timestamp in entries:
        if reading != "ERR":
            if sensor_id not in sensor_data:
                sensor_data[sensor_id] = {"count": 1, "average": int(reading), "latest": int(reading)}
            else:
                sensor_data[sensor_id]["count"] += 1
                sensor_data[sensor_id]["average"] = (sensor_data[sensor_id]["average"] * sensor_data[sensor_id]["count"] + int(reading)) // (sensor_data[sensor_id]["count"] + 1)
                if timestamp > sensor_data[sensor_id]["latest"]:
                    sensor_data[sensor_id]["latest"] = int(reading)

    return {sensor: data for sensor, data in sensor_data.items() if data["count"] > 0}

def summarize_sales(records):
    summary = {}
    for name, category, quantity, price in records:
        if category not in summary:
            summary[category] = {"items": 0, "revenue": 0, "top_product": ""}
        summary[category]["items"] += quantity
        total_revenue = quantity * price
        summary[category]["revenue"] += total_revenue
        if not summary[category]["top_product"] or (total_revenue > summary[category]["top_product_revenue"] or 
                                                    (total_revenue == summary[category]["top_product_revenue"] and name < summary[category]["top_product"])):
            summary[category]["top_product"] = name
            summary[category]["top_product_revenue"] = total_revenue
    return summary

def sensor_summary(entries):
    summary = {}
    for entry in entries:
        sensor_id, reading, timestamp = entry
        if reading != "ERR":
            if sensor_id not in summary:
                summary[sensor_id] = {"count": 0, "total_sum": 0, "latest_timestamp": -1}
            summary[sensor_id]["count"] += 1
            summary[sensor_id]["total_sum"] += int(reading)
            if timestamp > summary[sensor_id]["latest_timestamp"]:
                summary[sensor_id]["latest_timestamp"] = timestamp
    for sensor_id in list(summary.keys()):
        if summary[sensor_id]["count"] == 0:
            del summary[sensor_id]
        else:
            summary[sensor_id]["average"] = summary[sensor_id]["total_sum"] // summary[sensor_id]["count"]
    return summary
